import sys

def xor(x, y):
    return x ^ y

def ask_question(c, d):
    print(f"? {c} {d}")
    sys.stdout.flush()
    response = int(input())
    return response

def find_numbers():
    a = 0
    b = 0
    mask = 1 << 29

    for _ in range(62):
        if mask == 0:
            break

        response_a = ask_question(mask, 0)
        response_b = ask_question(0, mask)

        if response_a == 1:
            a |= mask
        elif response_a == -1:
            a &= ~mask

        if response_b == 1:
            b |= mask
        elif response_b == -1:
            b &= ~mask

        mask >>= 1

    print(f"! {a} {b}")
    sys.stdout.flush()

find_numbers()
